class Evaluator:
    def __init__(self, expression):
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expr: str):
        tokens = []
        number = ''
        for char in expr:
            if char.isspace():
                continue
            if char in '0123456789.':
                number += char
            else:
                if number:
                    tokens.append(float(number))
                    number = ''
                if char in '+-*/()':
                    tokens.append(char)
        if number:
            tokens.append(float(number))
        return tokens

    def _parse_expression(self):
        total = self._parse_term()
        while self.pos < len(self.tokens):
            op = self.tokens[self.pos]
            if op in '+-':
                self.pos += 1
                if op == '+':
                    total += self._parse_term()
                elif op == '-':
                    total -= self._parse_term()
            else:
                break
        return total

    def _parse_term(self):
        total = self._parse_factor()
        while self.pos < len(self.tokens):
            op = self.tokens[self.pos]
            if op in '*/':
                self.pos += 1
                if op == '*':
                    total *= self._parse_factor()
                elif op == '/':
                    total /= self._parse_factor()
            else:
                break
        return total

    def _parse_factor(self):
        token = self.tokens[self.pos]
        if isinstance(token, float):
            self.pos += 1
            return token
        elif token == '(':
            self.pos += 1
            result = self._parse_expression()
            self.pos += 1  # skip ')'
            return result
        raise ValueError("Unexpected token")

